def clean(df):
    df = df.copy()
    # Normalize Region: strip whitespace and fix case variants (e.g. 'West ', 'South ', 'east' -> 'West','South','East')
    if 'Region' in df.columns:
        mask = df['Region'].notna()
        df.loc[mask, 'Region'] = df.loc[mask, 'Region'].astype(str).str.strip().str.title()
    # Ensure numeric types for Quantity/Price
    for c in ['Quantity','Price']:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')
    # Remove exact duplicate rows (Order_ID unique)
    df = df.drop_duplicates()
    df = df.drop_duplicates(subset=['Order_ID'], keep='first')
    # Quantity must be >=1 (positive whole number) - remove out-of-range/negative rows
    if 'Quantity' in df.columns:
        df = df[df['Quantity'] >= 1]
    # Price must be >=0
    if 'Price' in df.columns:
        df = df[df['Price'] >= 0]
    # Recompute Revenue = Quantity * Price (cross-column rule)
    if 'Quantity' in df.columns and 'Price' in df.columns:
        df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    # total revenue by region for Electronics
    d = df.copy()
    # filter Electronics category
    if 'Category' in d.columns:
        d = d[d['Category'] == 'Electronics']
    # drop missing group keys
    d = d.dropna(subset=['Region'])
    if d.empty:
        return {}
    # ensure Revenue numeric
    d['Revenue'] = pd.to_numeric(d['Revenue'], errors='coerce')
    grouped = d.groupby('Region', dropna=True)['Revenue'].sum()
    # convert to plain dict, join multi-column labels with " | " if needed (single column here)
    result = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        # months would be formatted as YYYY-MM, not needed here
        key = str(k)
        # convert numpy types to python int/float
        if pd.isna(v):
            continue
        val = float(v) if isinstance(v, float) or v != int(v) else int(v)
        # keep as int when possible
        try:
            if float(val).is_integer():
                val = int(val)
        except:
            pass
        result[key] = val
    return result
